preConditionHook:
// The entry bar is bar [0] on the bar the entry fills, where BarsSinceEntry()
// is 0 (EL_FEATURES.md `barssinceentry`, VERIFIED). Its four prices are
// captured there and read on every later bar of the position, so the stop
// never indexes back by the position's age.
if (el_eq((double)ctx.BarsSinceEntry(), 0.0)) {
    entryBarOpen = open[0];
    entryBarHigh = high[0];
    entryBarLow = low[0];
    entryBarClose = close[0];
}
